 file:[['打开压缩文件','open','Ctrl+O'],['输入文件路径…','open-path',''],['最近的文件','recent-menu',''],['新建压缩文件','compress','Ctrl+N'],null,['关闭当前标签','close-archive','Ctrl+W'],['关闭所有标签','close-all-tabs',''],['另存为…','save-as',''],['删除压缩文件','recycle-archive','Ctrl+Del'],['打开压缩文件位置','reveal',''],null,['测试压缩文件','test','Ctrl+T'],['解压文件','extract','Ctrl+E'],['解压并移入回收站…','extract-recycle',''],null,['退出','exit','Alt+F4']],
