function updateToolbar(){root.querySelectorAll('#oa-toolbar [data-action],#oa-primary-action [data-action]').forEach(b=>{const a=b.dataset.action;b.disabled=(!s.archive&&!['open','compress','more-menu'].includes(a))||!!s.active;});if($('oa-selection-actions')){$('oa-selection-actions').hidden=!s.selected.size;$('oa-selected-count').textContent=`已选 ${s.selected.size} 个项目`;$('oa-selection-actions').querySelector('[data-action=rename]').disabled=s.selected.size!==1;}root.querySelectorAll('[data-view]').forEach(b=>{b.setAttribute('aria-current',String(b.dataset.view===(['tool','advanced'].includes(s.page)?'tools':s.page)));});}
function renderChrome(){renderArchiveTabs();root.dataset.page=s.page;$('oa-heading').innerHTML=s.page==='files'?`<div class="oa-heading-copy"><span class="oa-archive-symbol">${icon('archive')}</span><div><h1>${s.archive?esc(filename(s.archive)):'文件'}</h1><p>${s.archive?`${esc(filename(s.archive).split('.').pop().toUpperCase())} 压缩文件 · ${s.entries.length} 个条目`:'轻透、专注的本地归档工作空间'}</p></div></div><div id="oa-primary-action">${s.archive?btn('解压','extract','primary','folder-output'):''}</div>`:'';$('oa-toolbar').innerHTML=btn('打开','open','','folder-open')+btn('新建','compress','','plus')+'<span class="oa-divider"></span>'+btn('添加','add','','plus')+'<span class="oa-spacer"></span>'+(s.archive?btn('解压','extract','primary','folder-output'):'');$('oa-heading').hidden=s.page!=='files'||!!s.archive;$('oa-toolbar').hidden=s.page!=='files';const folders=new Set(['']);for(const e of s.entries){const parts=e.name.replaceAll('\\','/').split('/').filter(Boolean);if(!e.is_dir)parts.pop();let p='';for(const part of parts){p+=part+'/';folders.add(p);}}$('oa-tree').innerHTML=[...folders].sort().filter(p=>![...s.collapsed].some(c=>p!==c&&p.startsWith(c))).map(p=>{const depth=Math.max(0,p.split('/').filter(Boolean).length),hasChildren=[...folders].some(x=>x!==p&&x.startsWith(p));return `<div class="oa-tree-row" style="--depth:${depth}">${hasChildren?`<button class="oa-tree-toggle" data-tree-toggle="${esc(p)}" aria-label="${s.collapsed.has(p)?'展开':'折叠'} ${esc(p||'根目录')}" aria-expanded="${!s.collapsed.has(p)}">${icon('chevron')}</button>`:'<span class="oa-tree-toggle"></span>'}<button data-tree="${esc(p)}" aria-current="${p===s.folder&&s.page==='files'}">${icon(p?'folder':'archive')}<span>${esc(p?p.split('/').filter(Boolean).pop():s.archive?filename(s.archive):'未打开压缩文件')}</span></button></div>`;}).join('');updateToolbar();}
function showMenu(group,anchor){const anchorRect=root.querySelector('[data-action=app-menu]').getBoundingClientRect();const items=menuGroups[group]||[];const box=$('oa-menu');box.innerHTML=`<div class="oa-submenu-head">${btn('返回','more-menu','quiet')}<strong>${({file:'文件',edit:'编辑',find:'查找',options:'选项',view:'视图',tools:'工具',help:'帮助'})[group]}</strong></div>`+items.map(it=>it?`<button role="menuitem" data-action="${it[1]}"><span>${it[0]}</span><small>${it[2]}</small></button>`:'<hr>').join('');positionMenu(box,{getBoundingClientRect:()=>anchorRect});box.querySelector('button')?.focus();}
function selectRow(name,event){window.getSelection()?.removeAllRanges();const list=visibleEntries().map(e=>e.name),a=list.indexOf(s.anchor),b=list.indexOf(name),extend=event.ctrlKey||event.metaKey;if(event.shiftKey&&a>=0&&b>=0){const range=list.slice(Math.min(a,b),Math.max(a,b)+1);s.selected=extend?new Set([...s.selected,...range]):new Set(range);}else if(extend){s.selected.has(name)?s.selected.delete(name):s.selected.add(name);s.anchor=name;}else{s.selected=new Set([name]);s.anchor=name;}refreshSelection();}
function refreshSelection(){for(const tr of root.querySelectorAll('[data-row]')){const selected=s.selected.has(tr.dataset.row);tr.classList.toggle('selected',selected);const box=tr.querySelector('[data-select]');if(box)box.checked=selected;}const list=visibleEntries();if($('qa-selection'))$('qa-selection').textContent=`${list.length} 个项目 · 已选 ${s.selected.size} 项`;if($('qa-all')){$('qa-all').checked=list.length>0&&list.every(e=>s.selected.has(e.name));$('qa-all').indeterminate=list.some(e=>s.selected.has(e.name))&&!$('qa-all').checked;}updateToolbar();}
function showTool(op,title){if($('qa-tools')?.contentWindow?.obzBusy){toast('请先等待或取消当前工具任务。');return;}s.toolOp=op;s.toolTitle=title;navigate('tool');}
let destinationRequest=0;
async function setDestination(path){if(!path)return;const input=$('qa-destination'),list=$('oa-destination-folders');if(!input||!list)return;const request=++destinationRequest;input.value=path;const dirs=await invoke('list_directory',{path});if(request!==destinationRequest||input!==$('qa-destination')||list!==$('oa-destination-folders')||input.value!==path)return;list.innerHTML=dirs.map(e=>`<button data-directory="${esc(e.path)}">${icon('folder')} ${esc(e.name)}</button>`).join('')||'<p class="qa-sub">没有子文件夹</p>';}

const baseAction=action;
action=async a=>{if($('qa-tools')?.contentWindow?.obzBusy&&!['keep-running','cancel-exit','close'].includes(a)){toast('请先等待或取消当前工具任务。');return;}switch(a){case'associations':navigate('associations');if(s.page==='associations')await loadAssociations();return;case'associations-refresh':await loadAssociations();return;case'associations-save':await saveAssociations();return;case'default-apps':await invoke('open_default_apps');toast('请在 Windows 默认应用中选择 qing-zip，完成后返回刷新状态。');return;case'more-menu':case'app-menu':showMore();return;case'extract-recycle':extract(true);return;case'all-tools':s.advancedTab='archive-tools';navigate('advanced');return;case'tools-home':navigate('tools');return;case'files-home':navigate('files');return;case'comment':{if(!s.archive)throw Error('请先打开 ZIP 压缩文件。');const r=await run({operation:'comment-get',path:s.archive},'读取注释',{silent:true});dialog('压缩文件注释',`<label class="qa-field">ZIP 注释<textarea id="oa-comment">${esc(r.comment)}</textarea></label>`,btn('取消','close')+btn('保存','comment-save','primary'));}return;case'comment-save':{const name=$('oa-comment').value;await run({operation:'comment-set',path:s.archive,name},'保存注释');}return;case'settings':navigate('settings');return;case'profiles':s.advancedTab='automation';navigate('advanced');return;case'batch':s.advancedTab='batch';navigate('advanced');return;case'close-archive':closeArchiveTabs('current');return;case'close-all-tabs':closeArchiveTabs('all');return;case'refresh-archive':if(s.archive)await openArchive(s.archive,s.password,{refresh:true});return;case'exit':await invoke('window_action',{action:'close'});return;case'find':$('qa-search')?.focus();return;case'select-all':visibleEntries().forEach(e=>s.selected.add(e.name));if($('qa-rows'))rows();return;case'invert':visibleEntries().forEach(e=>s.selected.has(e.name)?s.selected.delete(e.name):s.selected.add(e.name));if($('qa-rows'))rows();return;case'toggle-tree':root.dataset.tree=root.dataset.tree==='hidden'?'shown':'hidden';return;case'toggle-status':root.dataset.status=root.dataset.status==='hidden'?'shown':'hidden';return;case'toolbar-large':case'toolbar-small':case'toolbar-hidden':root.dataset.toolbar=a.slice(8);return;case'details':case'icons':s.listStyle=a;saveViewPreference();render();return;case'reverse-sort':s.reverse=!s.reverse;rows();syncViewControls();return;case'preview-selected':if(s.selected.size!==1)throw Error('请选中一个文件或文件夹。');await entry([...s.selected][0],{preview:true});return;case'codepage':dialog('文件名代码页',`<label class="qa-field">编码<select id="oa-codepage">${opts([['','自动检测'],['65001','UTF-8'],['936','简体中文 GBK'],['950','繁体中文 Big5'],['949','韩文'],['932','日文 Shift-JIS'],['437','OEM 437']],s.codepage||'')}</select></label>`,btn('取消','close')+btn('应用','codepage-apply','primary'));return;case'codepage-apply':s.codepage=$('oa-codepage').value?Number($('oa-codepage').value):null;await openArchive(s.archive,s.password,{refresh:true});return;case'recent-menu':showRecentDialog();return;case'save-as':if(!s.archive)throw Error('请先打开压缩文件。');{if(/\.\d{3,}$/.test(s.archive))throw Error('分卷请先解压后重新压缩，以免遗漏其他卷。');const dest=await invoke('pick_copy_save',{path:s.archive});if(dest){await invoke('copy_archive',{path:s.archive,dest});toast('已另存为 '+dest);}}return;case'reveal-output':{const r=s.jobs.at(-1)?.result;const path=r?.destination||r?.outputs?.[0];if(path)await invoke('reveal_path',{path});}return;case'reveal':if(s.archive)await invoke('reveal_path',{path:s.archive});return;case'recycle-archive':if(s.archive)dialog('删除压缩文件',`<p>将 ${esc(filename(s.archive))} 移到回收站？</p>`,btn('取消','close')+btn('移到回收站','recycle-confirm','danger'));return;case'recycle-confirm':await invoke('recycle_paths',{paths:[s.archive]});close();await action('close-archive');return;case'copy-path':await navigator.clipboard.writeText([...s.selected].map(n=>s.archive+' / '+n).join('\n')||s.archive);toast('已复制路径');return;case'paste-files':{const paths=await invoke('clipboard_paths',{paths:null});if(!paths.length)throw Error('剪贴板中没有文件。');await run({operation:'add',path:s.archive,inputs:paths,options:archiveOptions()},'添加文件');await openArchive(s.archive,s.password,{refresh:true});}return;case'copy-files':{if(!s.selected.size)throw Error('请选中要复制的文件。');const names=[...s.selected],dest=await invoke('clipboard_directory');await run({operation:'extract',path:s.archive,dest,options:{selected:names,overwrite:'error',password:s.password||null,codepage:s.codepage||null}},'复制文件');await invoke('clipboard_paths',{paths:names.map(n=>dest+'\\'+n.replaceAll('/','\\'))});toast('文件已复制到剪贴板，可在资源管理器中粘贴。');}return;case'vault-tool':showTool('vault-list','密码管理器');return;case'repair-tool':showTool('repair','修复 ZIP 压缩包');return;case'recover-tool':showTool('recover','密码恢复');return;case'checksum-tool':showTool('checksum','文件校验值');return;case'about':dialog('关于 qing-zip',`<p>qing-zip ${esc(appVersion)}</p><p class="qa-sub">本地压缩与解压工具。第三方组件许可随程序附带。</p>`,btn('关闭','close'));return;case'help':dialog('使用说明','<p>打开压缩包后，单击选择条目，双击进入文件夹或查看文件。Ctrl / Shift 可多选。</p><p>Ctrl+N 新建，Ctrl+E 解压，Ctrl+T 测试，F2 重命名，Del 删除包内条目。</p><p>Ctrl+Tab 切换标签，Ctrl+Shift+Tab 反向切换，Ctrl+W 关闭当前标签，Ctrl+R 刷新当前标签。标签右键可关闭其他或全部。</p><p>文本双击只读预览；图片双击用系统默认看图程序打开原图。大图标模式可用 Ctrl+滚轮调整尺寸。</p><p>工具菜单提供修复、密码恢复、校验值和批量处理。</p>',btn('关闭','close'));return;}return baseAction(a);};
root.addEventListener('dblclick',e=>{if(e.target.closest('input'))return;const row=e.target.closest('[data-row]');if(row)entry(row.dataset.row).catch(error);});
let lastSelectShift=false,dragCandidate=null,dragBusy=false,suppressRowClick=false;
root.addEventListener('mousedown',e=>{if(e.target.closest('[data-row]')&&!e.target.closest('input'))e.preventDefault();});
root.addEventListener('dragstart',e=>{if(e.target.closest('[data-row]'))e.preventDefault();});
root.addEventListener('click',e=>{if(suppressRowClick&&e.target.closest('[data-row]')){e.preventDefault();e.stopImmediatePropagation();suppressRowClick=false;}},true);
root.addEventListener('pointerdown',e=>{lastSelectShift=e.shiftKey;if(e.button!==0||s.active||dragBusy||!overlay.hidden)return;const row=e.target.closest('[data-row]');if(row&&!e.target.closest('input')&&!e.shiftKey&&!e.ctrlKey&&!e.metaKey)dragCandidate={name:row.dataset.row,x:e.clientX,y:e.clientY};});
root.addEventListener('pointerup',()=>{dragCandidate=null;});
root.addEventListener('pointercancel',()=>{dragCandidate=null;});
root.addEventListener('pointermove',e=>{const c=dragCandidate;if(!c||!(e.buttons&1)||Math.hypot(e.clientX-c.x,e.clientY-c.y)<6)return;dragCandidate=null;suppressRowClick=true;if(!s.selected.has(c.name))selectRow(c.name,{});dragSelection().catch(error).finally(()=>{dragBusy=false;setTimeout(()=>suppressRowClick=false,300);});});
async function dragSelection(){if(dragBusy||s.active)return;dragBusy=true;const names=[...s.selected],path=s.archive,password=s.password||null,codepage=s.codepage||null;if(names.length>512)throw Error('一次最多拖出 512 个文件或文件夹。');toast('正在准备拖出文件，请保持按住鼠标；松开可取消拖放。');const dest=await invoke('clipboard_directory');await run({operation:'extract',path,dest,options:{selected:names,overwrite:'error',password,codepage}},'准备拖出文件',{silent:true});const copied=await invoke('drag_paths',{paths:names.map(n=>dest+'\\'+n.replaceAll('/','\\'))});toast(copied?'文件已交给目标文件夹复制。':'已取消拖放，压缩包保持不变。');}
const scrollTimers=new WeakMap();root.addEventListener('scroll',e=>{const el=e.target;if(!(el instanceof HTMLElement))return;el.classList.add('oa-scrolling');clearTimeout(scrollTimers.get(el));scrollTimers.set(el,setTimeout(()=>el.classList.remove('oa-scrolling'),900));},true);
root.addEventListener('click',e=>{if(e.target.closest('#oa-menu')||e.target.closest('[data-menu]')||e.target.closest('[data-action=more-menu]'))return;$('oa-menu').hidden=true;const row=e.target.closest('[data-row]');if(row&&!e.target.closest('button,input'))selectRow(row.dataset.row,e);});
root.addEventListener('contextmenu',e=>{const recent=e.target.closest('[data-recent]');if(recent){e.preventDefault();showRecentContext(recent,e);return;}const tab=e.target.closest('[data-tab-container]');if(tab){e.preventDefault();showArchiveTabMenu(tab.dataset.tabContainer,e);return;}const row=e.target.closest('[data-row]');if(row){e.preventDefault();if(!s.selected.has(row.dataset.row))selectRow(row.dataset.row,{});showMenu('edit',{getBoundingClientRect:()=>({left:e.clientX,bottom:e.clientY})});}});
document.addEventListener('keydown',e=>{if(!overlay.hidden)return;const key=e.key.toLowerCase(),ctrl=e.ctrlKey||e.metaKey;if(ctrl&&key==='tab'){e.preventDefault();cycleArchiveTab(e.shiftKey?-1:1);return;}if(ctrl&&key==='w'){e.preventDefault();closeArchiveTabs('current');return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const map=ctrl?{o:'open',n:'compress',e:'extract',t:'test',w:'close-archive',r:'refresh-archive',f:'find',a:'select-all',c:'copy-files',v:'paste-files'}:{f1:'about',f2:'rename',f4:'close-archive',f5:'settings',f6:'close-archive',f7:'toggle-tree',delete:'delete',insert:'add',backspace:'up'};const a=ctrl&&e.shiftKey&&key==='m'?'comment':ctrl&&key==='delete'?'recycle-archive':map[key];if(a&&s.page!=='files'&&!['open','compress','exit','close-archive','settings','about','toggle-tree'].includes(a))return;if(a){e.preventDefault();action(a).catch(error);}});
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.archiveTab!==undefined){switchArchiveTab(b.dataset.archiveTab);return;}if(b.dataset.tabClose!==undefined){closeArchiveTabs('one',b.dataset.tabClose);return;}if(b.dataset.tabCloseOthers!==undefined){closeArchiveTabs('others',b.dataset.tabCloseOthers);return;}if(b.dataset.menu){showMenu(b.dataset.menu,b);return;}if(b.dataset.treeToggle!==undefined){const p=b.dataset.treeToggle;s.collapsed.has(p)?s.collapsed.delete(p):s.collapsed.add(p);renderChrome();return;}if(b.dataset.tree!==undefined){if(s.active||$('qa-tools')?.contentWindow?.obzBusy)throw Error('请先等待或取消当前任务。');s.folder=b.dataset.tree;s.search='';s.selected.clear();navigate('files');return;}if(b.dataset.jobOutput){const j=s.jobs.find(j=>j.id===b.dataset.jobOutput),path=j?.result?.destination||j?.result?.outputs?.[0];if(path)await invoke('reveal_path',{path});return;}if(b.dataset.launchTool){showTool(b.dataset.launchTool,b.dataset.toolTitle);return;}if(b.dataset.place){await setDestination(s.known?.[b.dataset.place]||'');return;}if(b.dataset.directory){await setDestination(b.dataset.directory);return;}if(b.dataset.window){await invoke('window_action',{action:b.dataset.window});return;}if(b.dataset.view){navigate(b.dataset.view);return;}if(b.dataset.theme){s.theme=b.dataset.theme;appearance();return;}if(b.dataset.recent!==undefined){const path=s.recent[Number(b.dataset.recent)];try{await openArchive(path);}catch(e){openDialog(path);error(e);}return;}if(b.dataset.entry){selectRow(b.dataset.entry,e);return;}if(b.dataset.sort){s.reverse=s.sort===b.dataset.sort?!s.reverse:false;s.sort=b.dataset.sort;rows();syncViewControls();return;}if(b.dataset.advanced){if($('qa-tools')?.contentWindow?.obzBusy)throw Error('请等待当前工具任务完成。');s.advancedTab=b.dataset.advanced;render();return;}if(b.dataset.tool){if($('qa-tools')?.contentWindow?.obzBusy)throw Error('请等待当前工具任务完成。');$('qa-tools').src=`tools.html?operation=${b.dataset.tool}&path=${encodeURIComponent(s.archive)}&codepage=${s.codepage||''}`;return;}if(b.dataset.profile!==undefined){compress(s.profiles[Number(b.dataset.profile)]);return;}if(b.dataset.profileDelete!==undefined){s.profiles.splice(Number(b.dataset.profileDelete),1);localStorage.setItem('qing-profiles',JSON.stringify(s.profiles));render();return;}if(b.dataset.action){$('oa-menu').hidden=true;await action(b.dataset.action)};}catch(e){error(e);}});
root.addEventListener('input',e=>{if(e.target.id==='oa-icon-size')setIconSize(Number(e.target.value));if(e.target.id==='qa-inputs')refreshSources();if(e.target.id==='qa-search'){s.search=e.target.value;s.selected.clear();rows();}});
