window.__TAURI__.event.listen('close-requested',()=>{if($('oa-exit-confirm'))return;s.returnPage=overlay.dataset.page;overlay.dataset.page='close-confirm';overlay.hidden=false;root.querySelector('.qa-shell').inert=true;overlay.querySelectorAll('.qa-dialog').forEach(e=>e.inert=true);const box=document.createElement('section');box.id='oa-exit-confirm';box.className='qa-dialog';box.style.position='absolute';box.style.zIndex='40';box.innerHTML='<h2>任务正在进行</h2><p>取消当前任务并关闭？已完成的输出会保留。</p><div class="qa-dialog-footer">'+btn('继续任务','keep-running')+btn('取消任务并退出','cancel-exit','danger')+'</div>';overlay.append(box);box.querySelector('button').focus();}).catch(error);

function syncRecycleOption(){const box=$('oa-recycle-after');if(!box)return;const partial=overlay.querySelector('[name=extract-scope]:checked')?.value==='selected',skip=$('qa-conflict')?.value==='skip',split=/\.(?:\d{3,}|z\d{2,}|r\d{2,})$|\.part\d+\.rar$/i.test(s.archive);const supported=/\.(zip|zipx|7z|tar|gz|gzip|bz2|bzip2|xz|tgz|tbz|tbz2|txz)$/i.test(s.archive);box.disabled=partial||skip||split||!supported;box.checked=!box.disabled&&s.recycleAfter;box.closest('label').title=box.disabled?'仅支持完整解压且不跳过已有文件的已验证单卷格式':'';}
