const isImage=name=>IMAGE_EXT.test(name),isText=name=>TEXT_EXT.test(name)||/^(readme|license|notice|changelog|authors|makefile|dockerfile|\.gitignore|\.editorconfig|\.env)$/i.test(filename(name));
