const TAB_FIELDS=['archive','entries','password','codepage','folder','search','sort','reverse','selected','collapsed','anchor','focusFile','listStyle','iconSize','lastDest'];
function archiveKey(path){return String(path).replaceAll('/','\\').replace(/^\\\\\?\\/,'').toLocaleLowerCase();}
let recentContextPath='',recentContextRow=null;
function showRecentDialog(){dialog('最近的文件',s.recent.map((p,i)=>`<button class="qa-recent-row" data-recent="${i}">${esc(p)}</button>`).join('')||'<p>没有最近记录</p>',btn('清空记录','clear-recent')+btn('关闭','close'));overlay.dataset.page='recent';}
function updateRecent(paths){const inDialog=overlay.dataset.page==='recent';s.recent=paths;localStorage.setItem('qing-recent',JSON.stringify(s.recent));$('oa-menu').hidden=true;render();if(inDialog)showRecentDialog();}
function showRecentContext(row,event){const path=s.recent[Number(row.dataset.recent)];if(!path)return;recentContextPath=path;recentContextRow=row;const box=$('oa-menu');box.inert=false;box.innerHTML='<button role="menuitem" data-action="remove-recent">删除记录</button><button role="menuitem" data-action="clear-recent">清空记录</button>';positionMenu(box,{getBoundingClientRect:()=>({left:event.clientX,bottom:event.clientY})});box.querySelector('button').focus();}
root.addEventListener('keydown',e=>{const box=$('oa-menu');if(box.hidden||!box.querySelector('[data-action=remove-recent]'))return;const items=[...box.querySelectorAll('button')];if(e.key==='Escape'||e.key==='Tab'){e.preventDefault();e.stopImmediatePropagation();box.hidden=true;recentContextRow?.focus();return;}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();const index=items.indexOf(document.activeElement);items[e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowDown'?1:items.length-1))%items.length]?.focus();}},true);
