function emptyArchiveState(){Object.assign(s,{archive:'',entries:[],password:'',codepage:null,folder:'',search:'',sort:'name',reverse:false,selected:new Set(),collapsed:new Set(),anchor:null,focusFile:null,lastDest:undefined,listStyle:pref.listStyle==='icons'?'icons':'details',iconSize:Math.max(80,Math.min(256,Number(pref.iconSize)||144))});currentTabId=null;}
