function renderArchiveTabs(){const host=$('oa-archive-tabs');if(!host)return;host.hidden=!archiveTabs.length&&!pendingArchivePaths.length;root.dataset.tabs=String(!host.hidden);host.innerHTML=`<div class="oa-tab-list" role="tablist" aria-label="打开的压缩文件">${archiveTabs.map(t=>`<div class="oa-archive-tab ${t.id===currentTabId?'active':''}" data-tab-container="${t.id}"><button type="button" role="tab" data-archive-tab="${t.id}" aria-selected="${t.id===currentTabId}" title="${esc(t.archive)}">${icon('archive')}<span>${esc(filename(t.archive))}</span></button><button type="button" class="oa-tab-close" data-tab-close="${t.id}" aria-label="关闭 ${esc(filename(t.archive))}" title="关闭标签">${icon('x')}</button></div>`).join('')}</div>${pendingArchivePaths.length?`<span class="oa-pending-tabs" title="当前操作结束并关闭对话框后继续打开">待打开 ${pendingArchivePaths.length}</span>`:''}`;requestAnimationFrame(()=>{host.querySelector('[data-archive-tab][aria-selected="true"]')?.closest('.oa-archive-tab')?.scrollIntoView({block:'nearest',inline:'nearest'});});}
function switchArchiveTab(id){$('oa-menu').hidden=true;const tab=archiveTabs.find(t=>t.id===id);if(!tab)return;if(tabBusy()){toast('任务正在进行，请先等待或取消后再切换标签。');return;}saveCurrentTab();resetPreviewState();currentTabId=id;applyTab(tab);close();s.page='files';s.view='archive';render();requestAnimationFrame(()=>{if(currentTabId===id){main.scrollTop=tab.scrollTop||0;root.querySelector('.oa-tree-section').scrollTop=tab.treeScroll||0;root.querySelector(`[data-archive-tab="${id}"]`)?.scrollIntoView({block:'nearest',inline:'nearest'});}});}
function wipeTab(tab){tab.password='';tab.entries=[];tab.selected?.clear();tab.collapsed?.clear();}
function closeArchiveTabs(mode,id=currentTabId){$('oa-menu').hidden=true;if(tabBusy()){toast('任务正在进行，请先等待或取消后再关闭标签。');return;}saveCurrentTab();const remove=mode==='all'?archiveTabs.slice():mode==='others'?archiveTabs.filter(t=>t.id!==id):archiveTabs.filter(t=>t.id===id);if(!remove.length)return;const originalIndex=archiveTabs.findIndex(t=>t.id===currentTabId),removedCurrent=remove.some(t=>t.id===currentTabId);for(const tab of remove){archiveTabs.splice(archiveTabs.indexOf(tab),1);wipeTab(tab);}resetPreviewState();invoke('clear_preview_cache').catch(()=>{});close();if(removedCurrent){const next=archiveTabs[Math.min(Math.max(originalIndex,0),archiveTabs.length-1)];if(next){currentTabId=next.id;applyTab(next);}else emptyArchiveState();}s.page='files';s.view=s.archive?'archive':'home';render();}
